function partition(r){const types={VOCABULARY:'vocabulary',DICTIONARY_ENTRY:'dictionary',HANZI:'hanzi',PINYIN_PRACTICE:'pinyin',EXAMPLE_SENTENCE:'examples',GRAMMAR:'grammar',AUDIO_ASSET:'media/licensed_audio',TOPIC:'topics',QUESTION:'questions/licensed_only',SOURCE_METADATA:'metadata_only'};return (types[r.contentType]??'metadata_only')+'/'+(r.hskVersion==='HSK 2.0'?'hsk_2_0':r.hskVersion==='HSK 3.0'?'hsk_3_0':'unassigned')+'/'+r.sourceEdition.replace(/[^a-z0-9.-]/gi,'_')+'/'+(r.hskLevel?'hsk'+r.hskLevel.replace('-','_'):'unassigned');}
